/**
 * One path's last-known state in a projection.
 */
export type FsNode = { 
/**
 * Timestamp (epoch ms) of the last event that touched this path.
 */
ts: number; 
/**
 * The kind of the last event that touched this path (`created`/`modified`/`renamed`, ...).
 */
kind: string }
