export type ReplayLoad = { 
/**
 * The session's events (journal order) + `(min,max)` ts bounds + whole-run summary.
 */
replay: ReplayData; 
/**
 * The pre-existing-entries snapshot captured at watch-start, or `None` if the session never wrote
 * one — the fold then degrades to events-only reconstruction (an empty seed).
 */
baseline: Baseline | null }
/**
 * One entry in a browsed remote repo tree (CPE-434/435) — a file or folder, for the Repositories
 * left-pane view. Serialised to the frontend.
 */
export type RepoEntry = { name: string; path: string; is_dir: boolean; size: number }
/**
 * The git sync state of a local folder for the two-way-mirror status bar (CPE-462), flattened from
 * the repos crate's `RepoState` + safe `SyncPlan` for the frontend. `is_repo` is false for a
 * non-repo (or when `git` isn't available).
 */
export type RepoSyncStatus = { is_repo: boolean; branch: string | null; upstream: string | null; ahead: number; behind: number; dirty: boolean; 
/**
 * Planned safe steps: any of `pull-ff` / `pull-merge` / `pull-rebase` / `push`.
 */
actions: string[]; up_to_date: boolean; conflicts_possible: boolean; blocked: string | null; warnings: string[]; 
/**
 * True when the working tree currently has unmerged files (a merge/rebase left conflicts) — the
 * status bar surfaces a "Resolve…" entry into the CPE-496 resolver.
 */
conflicted: boolean }
/**
 * One concrete, ready-to-apply operation the CPE-1188 command executes in order. `from` is this
 * input's path just before the step; `to` is its path just after (equal to `from` for `tag`, which
 * never moves anything); `detail` is the primitive's argument — a tag label for `tag`, otherwise
 * informational only (the apply layer derives the actual rename/move/convert target from `to`).
 */
export type ResolvedOp = { from: string; kind: string; detail: string; to: string }
/**
 * A resolved run: the ops to apply (in order) and their inverses (same order — apply the inverses
 * in **reverse** to undo the run).
 */
export type ResolvedRun = { ops: ResolvedOp[]; inverses: InverseOp[] }
/**
 * The source a result came from. Declaration order is the section priority (actions first).
 * Deserialize too (not just Serialize): CPE-1214 sends it as a `spotlight_search` command *input*
 * (each `sources` entry is tagged with its `ResultKind`), so it must round-trip both ways over IPC.
 */
export type ResultKind = "action" | "folder" | "file" | "recent"
/**
 * The outcome of actually pruning a store: which manifests survived, which were removed (by the GFS
 * policy and/or the optional byte cap), and how many bytes were freed.
 */
export type RetentionApplyResult = { 
/**
 * Manifest ids still present after pruning, newest-first.
 */
kept: string[]; 
/**
 * Manifest ids actually removed — the GFS losers, plus any byte-cap eviction beyond them.
 */
pruned: string[]; 
/**
 * Total bytes freed across every prune in this apply.
 */
bytes_freed: number }
/**
 * How many buckets to keep at each granularity. `0` disables a tier.
 */
export type RetentionPolicy = { hourly: number; daily: number; weekly: number; monthly: number }
/**
 * The keep/prune verdict for a store under a policy, plus the store's current footprint — non-destructive,
 * safe to compute and show before [`apply`] touches anything.
 */
export type RetentionPreview = { 
/**
 * Manifest ids the policy would keep, newest-first.
 */
keep: string[]; 
/**
 * Manifest ids the policy would prune, oldest-first.
 */
prune: string[]; 
/**
 * The store's current total footprint in bytes (informational only — `preview` never mutates it).
 */
total_bytes: number }
/**
 * Outcome of a revert — an `OpResult`-style summary: how many actions applied, plus the ones that were
 * skipped (each carried as a failed [`OpResult`] with the skip reason), preserving the engine's
 * skip-on-error guarantee.
 */
export type RevertOutcome = { 
/**
 * Actions applied successfully.
 */
applied: number; 
/**
 * Actions skipped (missing blob, locked/permission-denied, path-safety refusal): `ok:false` +
 * `error` = the reason. Never fatal to the rest of the revert.
 */
skipped: OpResult[] }
/**
 * A preview of what reverting to a checkpoint would do: the restore-plan summary plus a **drift** report.
 * 
 * Drift = files that differ from the checkpoint but that this layer cannot attribute to the watched
 * agent. [`checkpoint_preview_revert`] takes an optional session id to resolve this:
 * - `session: None` (conservative default) — the classifier runs against an **empty** "agent-touched"
 * set, so every diverging path is surfaced as drift ("changed outside since checkpoint").
 * - `session: Some(sess)` (attribution-aware) — [`crate::revert_attribution::agent_touched`] computes
 * the set of paths `sess` itself mutated at/after the checkpoint, from the durable audit journal;
 * only paths **outside** that set are surfaced as drift, since the agent's own changes are expected,
 * not a warning-worthy conflict.
 */
export type RevertPreview = { 
/**
 * Files present in the checkpoint but gone now → would be recreated.
 */
creates: number; 
/**
 * Files present in both but changed → would be overwritten with the checkpoint content.
 */
overwrites: number; 
/**
 * Files created since the checkpoint → would be deleted.
 */
deletes: number; 
/**
 * Bytes the revert would write back (Create + Overwrite checkpoint sizes; deletes free space).
 */
bytes_written: number; 
/**
 * Total paths the revert would touch (`creates + overwrites + deletes`).
 */
total: number; 
/**
 * How many of those touched paths are drift (see the struct doc).
 */
drift_count: number; 
/**
 * The drifted paths, in plan order, so the UI can list them.
 */
drift_paths: string[] }
/**
 * One due root's capture + retention outcome, as reported by [`snapshot_run_due`].
 */
export type RunDueOutcome = { root: string; 
/**
 * The manifest id this scheduled capture just wrote.
 */
manifest_id: string; 
/**
 * CPE-1196's retention-prune result, applied to `root` right after the capture.
 */
retained: RetentionApplyResult }
/**
 * One folder's periodic-snapshot rule.
 */
export type ScheduleRule = { 
/**
 * The watched root this rule captures.
 */
root: string; 
/**
 * Minimum seconds that must elapse since the last run before `root` is due again.
 */
interval_s: number; 
/**
 * The retention policy [`snapshot_run_due`] applies to `root` after each scheduled capture.
 */
retention: RetentionPolicy; 
/**
 * A disabled rule is never returned by [`due`].
 */
enabled: boolean }
/**
 * One session's final cost + activity tallies. Mirrors the frontend `SessionMetrics`
 * (`src/lib/agentSessionMetrics.ts`) — camelCase on the wire to match it. **Advisory / best-effort:**
 * tokens + cost are text-scraped from the agent's own output; churn / files / wall-clock are
 * approximations. Not billing.
 */
export type SessionMetricsRecord = { 
/**
 * The agent session id this row belongs to.
 */
sessionId: string; 
/**
 * Agent catalog id (e.g. `"claude"`).
 */
agentId: string; 
/**
 * Human-readable agent name (e.g. `"Claude Code"`).
 */
agentName: string; 
/**
 * Provider the session ran through (e.g. `"openrouter"`).
 */
provider: string; 
/**
 * Model the session used (e.g. `"sonnet"`).
 */
model: string; 
/**
 * The session's working directory.
 */
cwd: string; 
/**
 * Epoch ms the session started (folded from its `started` announcement).
 */
startedAt: number; 
/**
 * Epoch ms the session ended (folded from its `ended` announcement / teardown).
 */
endedAt: number; 
/**
 * `ended_at - started_at` wall-clock, in milliseconds (best-effort — misses think time).
 */
wallClockMs: number; 
/**
 * Best-effort input tokens (text-scraped, advisory).
 */
inputTokens: number; 
/**
 * Best-effort output tokens (text-scraped, advisory).
 */
outputTokens: number; 
/**
 * `input_tokens + output_tokens`.
 */
totalTokens: number; 
/**
 * Best-effort USD cost (text-scraped, advisory — never billing).
 */
costUsd: number; 
/**
 * Distinct paths the session wrote to.
 */
filesTouched: number; 
/**
 * Σ |after.len − before.len| across every write (approximate churn).
 */
churnBytes: number; 
/**
 * Total fs-diff writes attributed to the session (not deduped by path).
 */
editCount: number; 
/**
 * Whether this row was flushed from a genuine `ended` announcement (`true`) or forced out at an
 * earlier point without one — e.g. the whole Agent Deck was closed while the session was still
 * running, so its process was reaped with no `ended` ever arriving (CPE-1626, epic CPE-731 slice b).
 * A forced row's `ended_at`/`wall_clock_ms` are stamped at flush time, not the session's real end, so
 * they may undercount. `#[serde(default = "default_ended_cleanly")]` reads an older row written before
 * this field existed as `true` (every row before CPE-1626 came from a real end) — never `false` by
 * omission, so an old row is never misread as forced-incomplete.
 */
endedCleanly?: boolean }
/**
 * Per-path outcome of a [`shred_paths`] batch run — `OpResult`-shaped (`path`/`ok`/`error`) so the
 * frontend can feed it straight into the generic per-path result summary used by every other
 * destructive op, plus the report fields a *successful* shred produced (zeroed on failure) so the UI
 * can also show pass/byte detail (CPE-1240, epic CPE-738).
 */
export type ShredResult = { path: string; ok: boolean; error: string; passes_run: number; bytes_written: number; removed: boolean }
/**
 * An overwrite scheme — how many passes and with what patterns.
 * 
 * `Deserialize` (unlike its sibling planning types, output-only) because this one also crosses the
 * IPC boundary as a `shred_paths` command **argument** (CPE-1240) — the frontend picks a scheme and
 * sends it in.
 */
export type ShredScheme = 
/**
 * One zero pass — fast; fine for most needs on spinning disks.
 */
"zero" | 
/**
 * One random pass.
 */
"random" | 
/**
 * DoD 5220.22-M style: zeros, ones, then random (3 passes).
 */
"dod_3" | 
/**
 * A Gutmann-lite spread (7 passes): random bookends around fixed byte patterns.
 */
"gutmann"
/**
 * A sidecar's health for the management panel (CPE-323): running state, the last error
 * that stopped it (if any), and recent log lines. Every string here is redacted.
 */
export type SidecarDiagnostics = { id: string; running: boolean; 
/**
 * The last start/crash error, redacted, or `None` if the sidecar is healthy.
 */
last_error: string | null; 
/**
 * Recent log lines, oldest first, already redacted.
 */
logs: DiagLogLine[] }
/**
 * One row in the platform management UI (CPE-274): a registered sidecar with its
 * identity, contract compatibility, running/enabled state, and consent picture.
 */
export type SidecarInfo = { id: string; name: string; version: string; contract: string; compatible: boolean; running: boolean; enabled: boolean; 
/**
 * Whether the sidecar's launchable binary actually resolves (CPE-863) — false = missing binary.
 */
binary_ok: boolean; requested: Capability[]; granted: Capability[] }
/**
 * What a repair attempt did, for the management panel (CPE-863). `binary_ok` is the re-checked binary
 * presence after the repair; `actions` are the plain-language steps taken.
 */
export type SidecarRepair = { id: string; binary_ok: boolean; actions: string[] }
/**
 * A set of visually-similar images: every path whose dHash landed in one near-duplicate cluster. Only
 * groups with 2+ members are produced (a singleton has no near-duplicate — dropped, mirroring
 * [`crate::perceptual::cluster`]).
 */
export type SimGroup = { paths: string[] }
/**
 * The result of a similar-image scan: the near-duplicate groups, how many image candidates were hashed,
 * and whether the file cap truncated the walk. Mirrors [`crate::duplicates::DupResult`].
 */
export type SimResult = { groups: SimGroup[]; files_scanned: number; truncated: boolean }
/**
 * A file the capture left out (oversize / over budget), surfaced so the caller can warn a checkpoint is
 * incomplete rather than silently dropping content. The string form of [`crate::snapshot::SkipReason`].
 */
export type SkippedInfo = { path: string; size: number; 
/**
 * `"oversize"` (larger than the per-file cap) or `"budget"` (would breach the store cap).
 */
reason: string }
/**
 * The manifest written by [`split_file`] and consumed by [`join_files`]. Deliberately small — just
 * enough to relocate the ordered parts and verify the reconstruction; the part width (zero-padding) is
 * re-derived from `part_count` rather than stored, and part sizes are derived from `total_size`/
 * `part_size`/`part_count` rather than stored per-part.
 */
export type SplitManifest = { 
/**
 * The original file's name (not path) — parts are named `<original_name>.NNN` and join's default
 * output uses this name.
 */
original_name: string; 
/**
 * Total size of the original file, in bytes.
 */
total_size: number; 
/**
 * Number of parts written. A 0-byte source has `part_count == 0` (no part files at all) — see
 * [`split_file`].
 */
part_count: number; 
/**
 * The requested part size in bytes. Every part is exactly this size except the last, which holds
 * the remainder.
 */
part_size: number; 
/**
 * SHA-256 of the whole original file, lowercase hex — recomputed from the concatenated parts on
 * join and compared against this.
 */
sha256: string }
/**
 * One aggregated result: the matched text, its kind, fuzzy score, and matched positions (for highlight).
 */
export type SpotResult = { text: string; kind: ResultKind; score: number; positions: number[] }
/**
 * A kind-grouped section of results (for a sectioned overlay).
 */
export type SpotSection = { kind: ResultKind; results: SpotResult[] }
/**
 * One symbol in the outline.
 */
export type Symbol = { name: string; kind: SymbolKind; 
/**
 * 1-based source line.
 */
line: number }
/**
 * The kind of a source symbol (drives the outline icon).
 */
export type SymbolKind = "function" | "method" | "struct" | "enum" | "trait" | "interface" | "class" | "module" | "constant" | "type_alias" | "heading"
export type TAURI_CHANNEL<TSend> = null
/**
 * The tags + colour label attached to one path.
 */
export type TagEntry = { tags?: string[]; label?: string }
/**
 * A captured folder structure that can be stamped out on demand.
 */
export type Template = { name: string; nodes?: Node[] }
/**
 * A gallery summary of one stored template: its name and how many dirs/files it stamps.
 */
export type TemplateSummary = { name: string; dirs: number; files: number }
/**
 * One terminal tab.
 */
export type TermTab = { id: number; title: string; cwd: string }
/**
 * Counts for a text file. Serialized to match the frontend `TextStats`.
 */
export type TextStats = { lines: number; words: number; chars: number; bytes: number }
/**
 * One requested thumbnail: a source file, the target tile edge, and the priority to enqueue it at if
 * it's not already cached. Sent from the frontend (CPE-1237): the visible window at `Priority::Visible`,
 * the prefetch margin at `Priority::Prefetch`.
 */
export type ThumbRequest = { path: string; target_px: number; priority: Priority }
/**
 * One resolved thumbnail, streamed back as it's ready. `data_url` is `None` when the format can't be
 * rendered (unreadable, unsupported, corrupt, oversized) — the frontend falls back to the type icon.
 */
export type ThumbResult = { path: string; target_px: number; data_url: string | null }
/**
 * Whether a batch copies or moves its sources.
 */
export type TransferKind = "copy" | "move"
/**
 * One item sitting in the OS Recycle Bin / Trash (epic CPE-1486, slice 1: browsable in-app Trash).
 * 
 * This DTO is deliberately `trash`-crate-free: the crate's `os_limited` listing API only exists on
 * Windows + Linux (see `docs/design/SERVER-ARCHITECTURE.md`), so the adapter in `src-tauri/src/lib.rs`
 * owns the `trash` dependency and maps its `TrashItem`/metadata into this plain, cross-platform-safe
 * struct via [`trash_entry`].
 */
export type TrashEntry = { 
/**
 * Platform-specific identifier of the trashed item (Windows: `IShellItem` display name; Linux: the
 * `.trashinfo` path) — opaque to the frontend, round-tripped back for restore/purge.
 */
id: string; name: string; 
/**
 * Full original path (parent + name) the item was trashed from.
 */
original_path: string; 
/**
 * Unix seconds since epoch when the item was moved to the trash.
 */
time_deleted: number; 
/**
 * Size in bytes, when known. `None` for a directory (the `trash` crate reports a directory's own
 * trash-metadata as an entry count, not a byte size) or when metadata couldn't be read for this item.
 */
size: number | null }
/**
 * One node of a scanned tree (CPE-779). Serialized camelCase to match the frontend `CompareNode`
 * (`isDir`).
 */
export type TreeNode = { name: string; isDir: boolean; size?: number | null; modified?: number | null; children?: TreeNode[] | null }
/**
 * A snapshot of a vault path's lifecycle state for the UI (CPE-1248). Carries no secret value.
 */
export type VaultStatus = { 
/**
 * The path is a `.cpevault` blob (recognised by its magic header, not its extension).
 */
is_vault: boolean; 
/**
 * The vault is currently unlocked (its plaintext is extracted in a live session directory).
 */
unlocked: boolean; 
/**
 * A passphrase for this vault is saved in the OS keychain.
 */
has_stored_passphrase: boolean }
/**
 * One postal address, flattened to a single readable line plus its (lower-cased) `TYPE` labels.
 */
export type VcardAddress = { 
/**
 * The address components (street, locality, region, postal code, country) joined with `, `.
 */
label: string; 
/**
 * Lower-cased `TYPE` labels, in declaration order.
 */
types: string[] }
/**
 * One email address with its (lower-cased) `TYPE` labels.
 */
export type VcardEmail = { 
/**
 * The email address, verbatim.
 */
address: string; 
/**
 * Lower-cased `TYPE` labels, in declaration order.
 */
types: string[] }
/**
 * One decoded contact (`VCARD` block). Every field is best-effort — a card missing a property leaves it
 * `None`/empty.
 */
export type VcardEntry = { 
/**
 * `FN` — the formatted display name.
 */
formatted_name: string | null; 
/**
 * `N` — the structured name assembled into a readable order (prefix given additional family suffix).
 */
name: string | null; 
/**
 * `ORG` — organisation (the `;`-separated units joined with `, `).
 */
org: string | null; 
/**
 * `TITLE` — job title.
 */
title: string | null; 
/**
 * `TEL` list.
 */
phones: VcardPhone[]; 
/**
 * `EMAIL` list.
 */
emails: VcardEmail[]; 
/**
 * `ADR` list.
 */
addresses: VcardAddress[]; 
/**
 * `URL` list.
 */
urls: string[]; 
/**
 * `BDAY` — birthday, verbatim (dates come in several vCard forms; shown as-is).
 */
birthday: string | null; 
/**
 * `true` when the card carried a `PHOTO` property (whose bytes are deliberately never returned).
 */
has_photo: boolean; 
/**
 * The `PHOTO` value's encoded byte length (base64 text or a URI), for a "photo present (~N)" note.
 * `0` when there is no photo.
 */
photo_size: number }
/**
 * One telephone number with its (lower-cased) `TYPE` labels (e.g. `["work", "cell"]`).
 */
export type VcardPhone = { 
/**
 * The dialling number, verbatim.
 */
number: string; 
/**
 * Lower-cased `TYPE` labels, in declaration order.
 */
types: string[] }
/**
 * A structured `.vcf` preview: the decoded contacts. A malformed file still returns whatever could be
 * parsed, with `error` describing what wasn't.
 */
export type VcardPreview = { 
/**
 * The decoded contacts, in file order.
 */
cards: VcardEntry[]; 
/**
 * Set when the input carried no `VCARD` block — the (empty) list still renders with this note.
 */
error: string | null }
/**
 * The video-tag columns a user can add to the details view — each maps to a friendly key
 * [`crate::video_meta_read::read_mp4`] emits.
 */
export type VideoTagColumn = "Title" | "Artist" | "Album" | "Year" | "Comment" | "Genre" | "Composer" | "Encoder" | "Copyright"
/**
 * A tracked item's usage: how many times it's been opened and when it was last opened (epoch seconds).
 */
export type Visit = { path: string; count: number; last_used_s: number }
/**
 * One resident volume's state, for `index_status` (so the UI can show what's indexed). Serialisable —
 * it's an `index_status` command return type.
 */
export type VolumeStatus = { volume_id: number; 
/**
 * Live entry count (tombstones excluded).
 */
entries: number; 
/**
 * Whether the crawl that produced this volume was truncated (dir cap or cancellation).
 */
truncated: boolean }
/**
 * One resolved watch action to execute: `kind` is `move` | `copy` | `rename`; `resolved` is the
 * destination directory (move/copy) or the new file name (rename), already expanded by the planner.
 */
export type WatchAction = { kind: string; resolved: string }
/**
 * The workbench's view of a folder (CPE-526/535): whether it's a git repo, the branch, and the diff.
 */
export type WorkbenchDiff = { is_repo: boolean; branch: string | null; diff: string }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "./invoke";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
